import React, { useCallback, useEffect, useRef, useState } from 'react';
import Prism from 'prismjs'
import Router from 'next/router'
import dynamic from 'next/dynamic'
import { message } from 'antd'
import { useSelector, useDispatch } from 'react-redux'
import ReactHtmlParser from 'react-html-parser'
import { inviteDeveloper } from 'redux/actions/video'
import { gotScreenList } from 'redux/actions/screenList'

import 'prismjs/components/prism-java'
import 'prismjs/components/prism-swift'

import ReactLoader from 'components/common/reactLoading'

import { changeCommonValue, fetchPlanHatApi } from 'redux/actions/common'
import { installCode, getAppDropdown } from 'redux/actions/appdropdown'

const recaptchaRef = React.createRef()

const WelcomePage = dynamic(import('./WelcomePage'), {
    loading: () => <ReactLoader />,
})

const DeveloperGuide = () => {
    const {
        currentAppReducer,
        profileReducer: { cookies, user },
        urlReducer: { appId },
        currentOrgReducer: {
            planLimit:{
                webSessionCount,
                sessionCount,
            },
            status,
        }
    } = useSelector((state) => state);

    const { urlReducer } = useSelector((state) => state)

    const dispatch = useDispatch()

    const [state, setState] = useState({
        loading: false,
        emailAddress: '',
        doItMyself: false,
        checkIntegrateDone: false,
        visible: false,
        emails: [],
        inviteRole: 1,
        privateMessage: '',
        successVisible: false,
        visibleFirstApp: false,
    });

    const refreshIntervalId = useRef(null)

    const showMeMySession = useCallback(async () => {
        const url = `/app/${currentAppReducer['_id']}/aisessions/list/1/?`
        await dispatch(getAppDropdown())
        dispatch(gotScreenList([]))
        Router.push(
            `/integration?appId=${currentAppReducer['_id']}&parentType=aiSessionsList`,
            url
        )
    }, [currentAppReducer, dispatch])
    
    const showModal = useCallback(() => {
        const text = `We are now using UXCam with ${currentAppReducer.name} to understand our users' behavior and to provide an improved user experience. To start recording our users’ sessions, please integrate the UXCam SDK in our app.`
        setState({
            ...state,
            visible: true,
            privateMessage: text,
            emails: [],
            inviteRole: 1,
        })
    }, [currentAppReducer.name, state])

    const handleOk = useCallback(async () => {
        setState({ ...state, loading: true })
        const team = []

        for (let i = 0; i < state.emails.length; i += 1) {
            team.push({
                email: state.emails[i],
                role: state.inviteRole,
            })
        }
        const captchaToken = await recaptchaRef.current.execute()
        const data = await inviteDeveloper(
            {
            team,
            privateMessage: state.privateMessage,
            captchaToken,
            },
            appId
        )
        if (data.success) {
            setState({ ...state, visible: false, loading: false })
            message.success(data.data.message)
        }  else {
            setState({ ...state, visible: false, loading: false })
            if (data.error.status !== 403) {
            if (data.error.message) {
                if (
                data.error.message &&
                data.error.message.includes('suspicious behavior')
                ) {
                    dispatch(changeCommonValue('isVisible_custom_popup', true))
                } else if (data.error.message.includes('upgrade your account')) {
                    dispatch(changeCommonValue(
                    'isVisible_custom_popup',
                    true,
                    ReactHtmlParser(data.error.message)
                    ))
                } else message.error(data.error.message)
            } else {
                message.info(data.error.email[0])
            }
            }
        }
    }, [appId, dispatch, state])
    
    const handleCancel = useCallback(() => {
        const text = `We are now using UXCam with ${currentAppReducer.name} to understand our users' behavior and to provide an improved user experience. To start recording our users’ sessions, please integrate the UXCam SDK in our app.`
        setState({ ...state, visible: false, privateMessage: text })
    }, [currentAppReducer.name, state])

    const doIt = useCallback(() => {
        if (!state.doItMyself) {
            setState({ ...state, doItMyself: true });
        }
    }, [state])

    const handleFirstAppCreated = useCallback(() => {
        try {
            localStorage.setItem('appCreatedInitial', false);
        } catch (err) {
            // silent fail
        }
        setState({ ...state, visibleFirstApp: false });
    }, [state])

    const CheckIntegrateDone = useCallback(() => {
        setState({ ...state, checkIntegrateDone: true });
    }, [state])

    const tabCallBack = useCallback(() => {
        if (state.checkIntegrateDone) {
            setState({ ...state, checkIntegrateDone: false });
        }
        Prism.highlightAll();
    }, [state])

    const handleRoleChange = useCallback((value) => {
        setState({ ...state, inviteRole: value })
    }, [state])
    
    const  handlePrivateMessage = useCallback((e) => {
        const { value } = e.target
        setState({ ...state, privateMessage: value })
    }, [state])
    
    const handleEmailChange = useCallback((_emails) => setState({ ...state, emails: _emails }), [state])

    useEffect(() => {
        if ( currentAppReducer ) {
            refreshIntervalId.current = setInterval(() => {
                const code = dispatch(installCode(currentAppReducer['_id'], cookies))
                const result = Promise.resolve(code)
                result.then(res => {
                    if (res?.isIntegrated) {
                    setState({ ...state, successVisible: true })
                    clearInterval(refreshIntervalId.current)
                    dispatch(fetchPlanHatApi({ action: 'Integration Completed'}))
                }
                })
            }, 5000)
        }
        Prism.highlightAll()

        return () => {
            clearInterval(refreshIntervalId.current)
            Prism.highlightAll()
        }
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [ cookies, currentAppReducer ])

    useEffect(() => {
        Prism.highlightAll()
    }, [state])
    
    if (!currentAppReducer) {
        return <ReactLoader />;
    }

    return <WelcomePage
        tabCallBack={tabCallBack}
        handleRoleChange={handleRoleChange}
        showModal={showModal}
        handleCancel={handleCancel}
        handleOk={handleOk}
        doIt={doIt}
        handlePrivateMessage={handlePrivateMessage}
        _checkIntegrateDone={CheckIntegrateDone}
        showMeMySession={showMeMySession}
        handleFirstAppCreated={handleFirstAppCreated}
        handleEmailChange={handleEmailChange}
        recaptchaRef={recaptchaRef}
        currentApp={currentAppReducer}
        cookies={cookies}
        user={user}
        urlQuery={urlReducer}
        isWebDisabled={webSessionCount === 0}
        isMobileDisabled={sessionCount === 0}
        planStatus={status}
        // eslint-disable-next-line react/jsx-props-no-spreading
        {...state}
    />
    
}

export default DeveloperGuide